class Solution {
public:
    int goodNodes(TreeNode* root) {
        return dfs(root, root->val);
    }
private:
    int dfs(TreeNode* node, int curMax) {
        if (!node) return 0;
        int newMax = max(curMax, node->val);
        int cnt = (node->val >= curMax) ? 1 : 0;
        cnt += dfs(node->left, newMax);
        cnt += dfs(node->right, newMax);
        return cnt;
    }
};
